import{_ as a,o as t,c as n,a3 as o}from"./chunks/framework.Cc-oPviL.js";const d=JSON.parse('{"title":"00 · 数据结构导读：数据怎么摆，决定了它有多快","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/dsa/00.md","filePath":"bagu/dsa/00.md"}'),l={name:"bagu/dsa/00.md"};function p(i,s,e,r,u,g){return t(),n("div",null,[...s[0]||(s[0]=[o(`<h1 id="_00-·-数据结构导读-数据怎么摆-决定了它有多快" tabindex="-1">00 · 数据结构导读：数据怎么摆，决定了它有多快 <a class="header-anchor" href="#_00-·-数据结构导读-数据怎么摆-决定了它有多快" aria-label="Permalink to &quot;00 · 数据结构导读：数据怎么摆，决定了它有多快&quot;">​</a></h1><blockquote><p>数据结构不是&quot;八种容器的名字&quot;，而是**&quot;用空间换时间&quot;的各种具体交易**。看懂这句话，这一模块就不用背了。</p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p>所有数据结构都在做同一件事：<strong>用额外的空间或额外的约束，换取某种操作更快</strong>。</p><ul><li>数组：浪费&quot;插入要挪动&quot;的代价，换取&quot;按下标随机访问 O(1)&quot;</li><li>哈希表：浪费空间（装不满），换取&quot;查找 O(1)&quot;</li><li>树：浪费指针，换取&quot;有序 + 查找 O(log n)&quot;</li><li>堆：只维护&quot;局部有序&quot;，换取&quot;取最值 O(1)&quot;</li></ul><p><strong>没有免费的午餐，只有不同的交易</strong>。选结构 = 选你要优化哪个操作、愿意付什么代价。</p><h2 id="生活类比-找东西的不同方式" tabindex="-1">生活类比：找东西的不同方式 <a class="header-anchor" href="#生活类比-找东西的不同方式" aria-label="Permalink to &quot;生活类比：找东西的不同方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>结构</th><th>场景</th></tr></thead><tbody><tr><td>数组</td><td>电影院的连排座位。知道排号就能直接坐下（O(1)），但中间要插一个人，后面全得挪</td></tr><tr><td>链表</td><td>寻宝游戏：每张纸条写着下一张在哪。插入方便，但要找第 10 张必须从第 1 张开始</td></tr><tr><td>栈</td><td>一摞盘子。只能从最上面拿、往最上面放</td></tr><tr><td>队列</td><td>排队买奶茶。先来的先走</td></tr><tr><td>哈希表</td><td>超市存包柜。按号码直接开柜，不用一个个找</td></tr><tr><td>二叉搜索树</td><td>公司组织架构。找一个人，从 CEO 开始&quot;大了往左、小了往右&quot;</td></tr><tr><td>堆</td><td>急诊分诊。不要求全员有序，只要求&quot;最严重的那个永远在最前面&quot;</td></tr><tr><td>图</td><td>地铁线路图。站点之间有关系，找最短路径</td></tr></tbody></table><h2 id="模块地图-5-篇怎么接" tabindex="-1">模块地图：5 篇怎么接 <a class="header-anchor" href="#模块地图-5-篇怎么接" aria-label="Permalink to &quot;模块地图：5 篇怎么接&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>01 复杂度 —— 怎么衡量&quot;快&quot;（全模块的度量尺）</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   +-- 02 线性结构：数组 / 链表 / 栈 / 队列 / 哈希表</span></span>
<span class="line"><span>   |      优化&quot;按下标访问&quot;或&quot;插入删除&quot;</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   +-- 03 树与堆：二叉树 / 平衡树 / 堆</span></span>
<span class="line"><span>   |      优化&quot;有序查找&quot;和&quot;取最值&quot;</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   +-- 04 图与并查集：最短路 / 拓扑排序 / 连通性</span></span>
<span class="line"><span>   |      处理&quot;多对多关系&quot;</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   +-- 05 排序与二分：把前面所有结构用起来</span></span>
<span class="line"><span>          排序是&quot;预处理&quot;，二分是&quot;利用有序&quot;</span></span></code></pre></div><p><strong>关键连接</strong>：</p><ul><li><strong>01 是尺子</strong>。后面所有&quot;这个结构更快&quot;的结论，都要用 01 的语言（O(n)、O(log n)）表述。</li><li><strong>02 的哈希表</strong> 和 <strong>03 的树</strong> 是&quot;查找&quot;的两种方案：哈希 O(1) 但无序，树 O(log n) 但有序。<strong>这个对比直接决定了数据库索引为什么用树不用哈希</strong>。</li><li><strong>03 的树</strong> 是 04 数据库 B+ 树的前置。<strong>不先懂二叉树和平衡树，B+ 树就是死记硬背</strong>。</li><li><strong>05 的排序</strong> 是所有算法的&quot;预处理步骤&quot;，而二分是&quot;利用有序&quot;的极致。</li></ul><h2 id="一条主线-为什么数据库用-b-树而不用哈希" tabindex="-1">一条主线：为什么数据库用 B+ 树而不用哈希 <a class="header-anchor" href="#一条主线-为什么数据库用-b-树而不用哈希" aria-label="Permalink to &quot;一条主线：为什么数据库用 B+ 树而不用哈希&quot;">​</a></h2><p>这条线把整个模块串起来，<strong>建议先看一遍</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问题：1000 万行数据，怎么快速找到某一行？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>方案 1：数组 + 线性扫描</span></span>
<span class="line"><span>  &gt; O(n)，1000 万次比较，太慢</span></span>
<span class="line"><span></span></span>
<span class="line"><span>方案 2：哈希表</span></span>
<span class="line"><span>  &gt; 查找 O(1)，很快</span></span>
<span class="line"><span>  &gt; 但：① 不支持范围查询（age &gt; 20 得全扫）</span></span>
<span class="line"><span>        ② 不支持排序（ORDER BY 用不上）</span></span>
<span class="line"><span>        ③ 哈希冲突退化，且扩容代价大</span></span>
<span class="line"><span>  &gt; 结论：等值查询可以，范围查询不行</span></span>
<span class="line"><span></span></span>
<span class="line"><span>方案 3：二叉搜索树</span></span>
<span class="line"><span>  &gt; 查找 O(log n)，且天然有序</span></span>
<span class="line"><span>  &gt; 但：① 退化成链表时是 O(n)（所以要平衡树）</span></span>
<span class="line"><span>        ② 每个节点只存一个值 &gt; 树高 log2(1000万) ≈ 24 层</span></span>
<span class="line"><span>        ③ 每层一次磁盘 IO &gt; 24 次 IO，太慢</span></span>
<span class="line"><span></span></span>
<span class="line"><span>方案 4：B 树（多叉）</span></span>
<span class="line"><span>  &gt; 每个节点存几百个值 &gt; 树高降到 3~4 层</span></span>
<span class="line"><span>  &gt; 磁盘 IO 从 24 次降到 3~4 次</span></span>
<span class="line"><span></span></span>
<span class="line"><span>方案 5：B+ 树（B 树的改良）</span></span>
<span class="line"><span>  &gt; 数据只在叶子节点，非叶子只存索引 &gt; 一个节点能装更多键 &gt; 树高更低</span></span>
<span class="line"><span>  &gt; 叶子节点用链表串起来 &gt; 范围查询直接顺序扫，不用回到根</span></span>
<span class="line"><span>  &gt; 结论：这是数据库的最终选择</span></span></code></pre></div><p><strong>看懂这条线，你就同时懂了：数组、哈希、二叉树、平衡树、B 树、B+ 树，以及它们各自的取舍</strong>。这比背六段定义有用得多。</p><h2 id="学习这个模块的方法" tabindex="-1">学习这个模块的方法 <a class="header-anchor" href="#学习这个模块的方法" aria-label="Permalink to &quot;学习这个模块的方法&quot;">​</a></h2><ol><li><strong>每个结构都问三个问题</strong>：它优化了哪个操作？代价是什么？什么场景下会退化？</li><li><strong>一定要手写</strong>。二分和快排的边界，不手写三遍永远记不住。</li><li><strong>不要背代码，背&quot;为什么这么写&quot;</strong>。比如二分为什么用 <code>left + (right-left)/2</code>（防溢出），为什么循环条件是 <code>left &lt;= right</code>（闭区间）。</li><li><strong>复杂度要能&quot;看出来&quot;</strong>，不是背出来的。看到&quot;每次砍一半&quot;就是 log n，看到&quot;嵌套两层&quot;就是 n²。</li></ol><h2 id="和其他模块的连接" tabindex="-1">和其他模块的连接 <a class="header-anchor" href="#和其他模块的连接" aria-label="Permalink to &quot;和其他模块的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/02">虚拟内存：让每个程序都以为自己独占一台机器</a>：数组快于链表的根本原因是缓存局部性，属于内存布局问题</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/01">索引与 B+ 树</a>：B+ 树是这里树结构的直接应用，一个节点 = 一个磁盘页（16KB）</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/02">事务与 ACID</a>：undo log 是链表、redo log 是环形数组，都是这里的基础结构</li><li><strong>&gt; 影响</strong> 工程实践：Redis 的跳表（有序链表 + 多级索引）、Java 的 HashMap（数组 + 链表 + 红黑树）、Kafka 的稀疏索引</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：为什么说&quot;所有数据结构都是空间换时间&quot;？这个说法有反例吗？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>大体成立，但不绝对</strong>。更准确的说法是&quot;<strong>用一种操作的代价，换另一种操作的效率</strong>&quot;。</p><ul><li>哈希表：确实是用空间（装不满的桶）换查找时间。</li><li>链表：反而是用<strong>时间</strong>换空间（插入快，但查找慢，且每个节点多一个指针的空间开销）。</li><li>数组：用&quot;插入慢&quot;换&quot;随机访问快&quot;，空间上还更省（没有指针）。</li><li>堆：用&quot;整体无序&quot;换&quot;取最值快&quot;。</li></ul><p>所以真正的统一表述是：<strong>没有一种结构在所有操作上都最优，选结构就是选&quot;哪个操作最重要&quot;</strong>。面试时这样答，比背&quot;空间换时间&quot;更显得懂。</p></details><p><strong>Q2：既然哈希表查找 O(1)，为什么不用它做数据库索引？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>三个致命问题：</p><ol><li><strong>不支持范围查询</strong>。<code>WHERE age &gt; 20</code> 用哈希只能全表扫，因为哈希把相邻的值打散了。B+ 树叶子有序且相连，范围查询直接顺序扫。</li><li><strong>不支持排序</strong>。<code>ORDER BY</code> 用不上哈希索引，只能额外排序。</li><li><strong>最左前缀失效</strong>。联合索引 <code>(a,b)</code>，只查 <code>b</code> 时哈希完全用不了；B+ 树可以利用前缀。</li></ol><p>哈希索引确实存在（MySQL 的 MEMORY 引擎、InnoDB 的自适应哈希索引），但只用于<strong>等值查询</strong>的加速，是补充而不是主力。</p></details><p><strong>Q3：为什么平衡树能保证 O(log n)，普通二叉搜索树不能？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为普通 BST 的形态取决于<strong>插入顺序</strong>。</p><p>按 <code>1,2,3,4,5</code> 顺序插入，树会退化成一条链（每个节点只有右孩子），查找变成 O(n)——和链表没区别。</p><p>平衡树（AVL、红黑树）通过<strong>旋转</strong>维持&quot;左右子树高度差不超过常数&quot;，强制树高保持在 O(log n)，所以最坏情况也是 O(log n)。</p><p>代价：每次插入/删除可能触发旋转，常数开销变大，实现也复杂得多。这就是&quot;用一点性能换最坏情况的保证&quot;。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;电影院座位&quot;类比会让人以为数组插入一定慢</strong>。在<strong>尾部</strong>追加是 O(1)（摊销），只有在中间插入才要挪动。</li><li><strong>&quot;哈希 O(1)&quot;是平均情况</strong>。最坏情况（全部冲突）是 O(n)，Java 8 之后冲突多了会转红黑树变成 O(log n)。</li><li><strong>&quot;树都是 O(log n)&quot;不成立</strong>。只有<strong>平衡</strong>的树才是；普通 BST 最坏 O(n)。</li><li><strong>复杂度忽略常数，但工程里常数很重要</strong>。O(log n) 的树在 n 很小时，可能比 O(n) 的数组还慢（缓存不友好 + 指针跳转）。</li><li><strong>&quot;堆是有序的&quot;是错的</strong>。堆只保证&quot;根是最值&quot;，其他位置无序。所以堆不能做范围查询，也不能中序遍历出有序序列。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能用一句话说清&quot;选数据结构本质是在权衡什么&quot;，并举出数组/链表/哈希/堆各自优化了哪个操作</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能画出模块地图，说出 5 篇之间的依赖关系（尤其&quot;树 &gt; B+ 树&quot;这条）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能完整讲出&quot;为什么数据库用 B+ 树&quot;那条主线（从数组 &gt; 哈希 &gt; BST &gt; B 树 &gt; B+ 树）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能说出哈希表不适合做数据库索引的三个原因</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能解释&quot;普通 BST 会退化成链表，平衡树怎么避免&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,31)])])}const q=a(l,[["render",p]]);export{d as __pageData,q as default};
